using System;using System.IO;using System.Reflection;using System.Collections;using UnityEngine;
namespace FashionFit {
 public static class MensCollectionScenario {
  [Serializable]public sealed class Result{public string status="passed",scope="Real menu/near-hand routes with injected Touch and manually stepped solver; no physical HMD";public int checks,outfits,contacts,exceptions;public bool menuRoute,rackPickup,pose,bimanual,release;public float maxPullM;}
  static Result result;static string folder;static FashionFitApp app;static RunwayVRHands hands;
  static void Check(bool ok,string label){result.checks++;if(!ok)throw new Exception(label);}
  static void Log(string a,string b,LogType t){if(t==LogType.Exception||t==LogType.Error)result.exceptions++;}
  public static Result Run(FashionFitApp owner,string output){app=owner;folder=output;Directory.CreateDirectory(folder+"/Contact");result=new Result();var mode=Physics.simulationMode;Application.logMessageReceived+=Log;
   try{Physics.simulationMode=SimulationMode.Script;app.Player.PrepareForVRTrial();app.Player.EnsureHands();hands=app.Player.Hands;app.Player.PreviewVRMenu();typeof(RunwayPlayer).GetProperty("InVR").SetValue(app.Player,true);typeof(RunwayPlayer).GetProperty("HeadTracked").SetValue(app.Player,true);var menu=app.Player.VRMenu;Check(menu&&menu.Buttons.Count==14,"Missing mens collection menu entry");var entry=menu.Buttons[13];Physics.SyncTransforms();Vector3 origin=entry.transform.position-entry.transform.forward*.23f;Quaternion q=Quaternion.LookRotation(entry.transform.forward);hands.Step(0,true,origin,q,0,0,1f/60);hands.Step(0,true,origin,q,0,1,1f/60);result.menuRoute=menu.Page==11;Check(result.menuRoute,"Actual Trigger ray cannot open mens collection");hands.ReleaseAll(false);
    int female=app.PoseStudio.Wearables[0].Look,walker=app.Look;var wear=app.PoseStudio.Wearables[1];var rig=app.PoseStudio.Rigs[1];
    for(int i=0;i<5;i++){
     menu.ActionButtons[i].Activate();menu.Hide();app.PoseStudio.SetHandles(false);Check(wear.Look==i+7,"Wrong male look selected");Check(app.Look==walker&&app.PoseStudio.Wearables[0].Look==female,"Male collection changed another mannequin");var asset=MensReferenceCollection.Asset(i+7);Check(asset&&asset.mesh&&asset.mesh.subMeshCount==4,"Missing independent outfit mesh/material groups");Check(asset.materials.Length==4&&asset.materials[0].GetTexture("_ClothNormal"),"Missing authored fabric normal");for(int k=0;k<30;k++)wear.Step(1f/60);hands.Hide();app.MaterialLab.ShowReadings=false;Export(wear,"Look"+(i+1)+"_Neutral");Capture(wear,"Look"+(i+1)+".png",false);Capture(wear,"Look"+(i+1)+"_Collar.png",true);
     var baseline=wear.Surface.MeshAt(0).vertices;int a=Closest(baseline,new Vector3(-.1f,1.30f,.17f)),b=Closest(baseline,new Vector3(.1f,1.30f,.17f));Vector3 left=wear.Surface.transform.TransformPoint(baseline[a]),right=wear.Surface.transform.TransformPoint(baseline[b]);Grip(0,left);Grip(1,right);result.bimanual=hands.HeldCount==2&&wear.Surface.GrabCount==2;Check(result.bimanual,"Cannot grip new outfit with both hands");for(int k=0;k<80;k++){hands.Step(0,true,left+Vector3.forward*.12f,Quaternion.identity,1,0,1f/60);hands.Step(1,true,right+Vector3.forward*.12f,Quaternion.identity,1,0,1f/60);wear.Step(1f/60);}float pull=Vector3.Distance(baseline[a],wear.Surface.MeshAt(0).vertices[a]);result.maxPullM=Mathf.Max(result.maxPullM,pull);Check(pull>.020f&&pull<.075f,"New garment has no bounded pull response");Export(wear,"Look"+(i+1)+"_Pulled");hands.Release(0,false);result.release=hands.HeldBy(1)&&wear.Surface.GrabCount==1;Check(result.release,"One-hand release lost remaining cloth hand");hands.ReleaseAll(false);for(int k=0;k<300;k++)wear.Step(1f/60);Export(wear,"Look"+(i+1)+"_Recovered");
     app.PoseStudio.SetHandles(true);RunwayPoseHandle handle=null;foreach(var h in rig.Handles)if(h.Bone.name=="LeftHand"){handle=h;break;}Check(handle,"Wrist handle missing");Vector3 hp=handle.transform.position,before=handle.Bone.position;Grip(0,hp);Check(hands.HeldBy(0)&&hands.HeldBy(0).IsJoint,"New clothes steal pose mode grip");for(int k=0;k<80;k++){hands.Step(0,true,hp+Vector3.up*.10f,Quaternion.identity,1,0,1f/60);wear.Step(1f/60);}result.pose=Vector3.Distance(before,handle.Bone.position)>.05f;Check(result.pose,"Mannequin cannot pose wearing new collection");Export(wear,"Look"+(i+1)+"_Posed");hands.ReleaseAll(false);app.PoseStudio.ResetPose(1);app.PoseStudio.SetHandles(false);result.outfits++;menu.SelectPage(11);
    }
    RunwayPickup sample=null;foreach(var item in app.Showroom.Items)if(item.Look==7){sample=item;break;}Check(sample,"Mens rack has no pickup sample");sample.transform.position=app.PoseStudio.Rigs[1].Avatar.transform.TransformPoint(new Vector3(0,1.25f,.15f))-sample.GetComponent<Collider>().bounds.center+sample.transform.position;Physics.SyncTransforms();result.rackPickup=app.Showroom.TryWear(sample)&&wear.Look==7;Check(result.rackPickup,"Mens rack sample does not equip on male");Check(result.exceptions==0,"Unity errors in collection scenario");
   }catch(Exception e){result.status="failed";File.WriteAllText(folder+"/failure.txt",e.ToString());throw;}finally{hands?.ReleaseAll(false);typeof(RunwayPlayer).GetProperty("InVR").SetValue(app.Player,false);Physics.simulationMode=mode;Application.logMessageReceived-=Log;File.WriteAllText(folder+"/verification.json",JsonUtility.ToJson(result,true));}return result;
  }
  static int Closest(Vector3[] p,Vector3 target){int best=0;float d=float.PositiveInfinity;for(int i=0;i<p.Length;i++){float n=(p[i]-target).sqrMagnitude;if(n<d){d=n;best=i;}}return best;}
  static void Grip(int side,Vector3 p){Physics.SyncTransforms();hands.Step(side,true,p,Quaternion.identity,0,0,1f/60);hands.Step(side,true,p,Quaternion.identity,1,0,1f/60);}
  static void Export(PoseWearable wear,string name){var avatar=wear.Rig.Avatar;var body=new Mesh();var old=avatar.Renderer.sharedMesh;avatar.Renderer.sharedMesh=avatar.BodyMesh;avatar.Renderer.BakeMesh(body);avatar.Renderer.sharedMesh=old;using(var w=new BinaryWriter(File.Create(folder+"/Contact/"+name+".bin"))){w.Write(0x53434631);Write(w,body.vertices,body.triangles);Write(w,wear.Surface.MeshAt(0).vertices,wear.Surface.MeshAt(0).triangles);}UnityEngine.Object.DestroyImmediate(body);result.contacts++;}
  static void Write(BinaryWriter w,Vector3[] p,int[] f){w.Write(p.Length);foreach(var v in p){w.Write(v.x);w.Write(v.y);w.Write(v.z);}w.Write(f.Length);foreach(int i in f)w.Write(i);}
  static void Capture(PoseWearable wear,string name,bool close){var avatar=wear.Rig.Avatar;var c=app.Player.View;c.rect=new Rect(0,0,1,1);c.transform.position=avatar.transform.TransformPoint(close?new Vector3(.48f,1.61f,.77f):new Vector3(.65f,1.35f,2.55f));c.transform.LookAt(avatar.transform.TransformPoint(close?new Vector3(0,1.48f,.10f):new Vector3(0,.99f,0)));var rt=new RenderTexture(1000,1200,24);var tex=new Texture2D(1000,1200,TextureFormat.RGB24,false);var previous=RenderTexture.active;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1000,1200),0,0);tex.Apply();File.WriteAllBytes(folder+"/"+name,tex.EncodeToPNG());}finally{c.targetTexture=null;RenderTexture.active=previous;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);}}
 }
 public sealed class MensCollectionPlayerVerification:MonoBehaviour {
  string output;
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){var args=Environment.GetCommandLineArgs();for(int i=0;i<args.Length-1;i++)if(args[i]=="-fashionMensVerify"){var test=new GameObject("Explicit mens reference QA").AddComponent<MensCollectionPlayerVerification>();test.output=args[i+1];break;}}
  IEnumerator Start(){Application.runInBackground=true;double end=Time.realtimeSinceStartupAsDouble+40;FashionFitApp app=null;while(!app||!app.Ready){app=FindObjectOfType<FashionFitApp>();if(Time.realtimeSinceStartupAsDouble>end){Application.Quit(1);yield break;}yield return null;}int code=0;try{MensCollectionScenario.Run(app,output);}catch(Exception e){Debug.LogException(e);code=1;}Application.Quit(code);}
 }
}
